{
  "name": "Database Backup and Account Defaulter Process",
  "resources": [
    {
      "name": "System",
      "capacity": 1,
      "resource_type": "system"
    },
    {
      "name": "Account Management",
      "capacity": 1,
      "resource_type": "department"
    },
    {
      "name": "Supervisor",
      "capacity": 1,
      "resource_type": "human"
    }
  ],
  "events": [
    {
      "id": "evt_start",
      "name": "Weekday morning process started",
      "event_position": "start",
      "trigger_type": "timer",
      "message_name": null
    },
    {
      "id": "evt_alert_230",
      "name": "Send alert to supervisor (2:30 pm deadline missed)",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Deadline 2:30 PM Alert"
    },
    {
      "id": "evt_alert_400",
      "name": "Send message to supervisor (4:00 pm deadline missed)",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Deadline 4:00 PM Alert"
    },
    {
      "id": "evt_send_table_am",
      "name": "Send table to account management",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Defaulting Accounts Table"
    },
    {
      "id": "evt_end",
      "name": "Process completed",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    }
  ],
  "tasks": [
    {
      "id": "task_backup_db",
      "name": "Backup database",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["ds_db"]
    },
    {
      "id": "task_check_defaulter_table",
      "name": "Check Account Defaulter table for new records",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["ds_db"],
      "output_data_ids": []
    },
    {
      "id": "task_check_crm_initial",
      "name": "Check CRM system for new returns",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["ds_crm"],
      "output_data_ids": []
    },
    {
      "id": "task_register_defaulters",
      "name": "Register all defaulting accounts and customers",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["ds_db"]
    },
    {
      "id": "task_check_advised_codes",
      "name": "Check if defaulting client codes have been previously advised",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["ds_db"],
      "output_data_ids": []
    },
    {
      "id": "task_produce_table",
      "name": "Produce table of defaulting accounts",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["ds_db"],
      "output_data_ids": ["do_defaulter_table"]
    },
    {
      "id": "task_check_230_deadline",
      "name": "Check if 2:30 pm deadline is met",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_check_crm_second",
      "name": "Check CRM system for new returns after report completion",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["ds_crm"],
      "output_data_ids": []
    },
    {
      "id": "task_reconcile",
      "name": "Reconcile with existing account defaulters table",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["ds_crm", "ds_db"],
      "output_data_ids": ["ds_db"]
    },
    {
      "id": "task_check_400_deadline",
      "name": "Check if 4:00 pm deadline is met",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    }
  ],
  "gateways": [
    {
      "id": "gw_new_records",
      "name": "New records found?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_rec_yes",
          "condition": "New records found"
        },
        {
          "flow_id": "sf_rec_no",
          "condition": "No new records found"
        }
      ]
    },
    {
      "id": "gw_crm_initial",
      "name": "New returns exist?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_crm_yes",
          "condition": "New returns exist"
        },
        {
          "flow_id": "sf_crm_no",
          "condition": "No new returns exist"
        }
      ]
    },
    {
      "id": "gw_advised",
      "name": "Client codes previously advised?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_adv_not",
          "condition": "Not previously advised"
        },
        {
          "flow_id": "sf_adv_yes",
          "condition": "Previously advised"
        }
      ]
    },
    {
      "id": "gw_230_deadline",
      "name": "Completed by 2:30 pm?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_230_yes",
          "condition": "Completed before 2:30 pm"
        },
        {
          "flow_id": "sf_230_no",
          "condition": "Not completed by 2:30 pm"
        }
      ]
    },
    {
      "id": "gw_230_merge",
      "name": "Merge 2:30 PM flow",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_crm_second",
      "name": "New returns filed?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_crm2_yes",
          "condition": "New returns filed"
        },
        {
          "flow_id": "sf_crm2_no",
          "condition": "No new returns filed"
        }
      ]
    },
    {
      "id": "gw_400_deadline",
      "name": "Completed by 4:00 pm?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_400_yes",
          "condition": "Completed before 4:00 pm"
        },
        {
          "flow_id": "sf_400_no",
          "condition": "Not completed by 4:00 pm"
        }
      ]
    },
    {
      "id": "gw_400_merge",
      "name": "Merge 4:00 PM flow",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": null
    }
  ],
  "sequence_flows": [
    {
      "id": "sf_1",
      "source_id": "evt_start",
      "target_id": "task_backup_db",
      "condition_name": null
    },
    {
      "id": "sf_2",
      "source_id": "task_backup_db",
      "target_id": "task_check_defaulter_table",
      "condition_name": null
    },
    {
      "id": "sf_3",
      "source_id": "task_check_defaulter_table",
      "target_id": "gw_new_records",
      "condition_name": null
    },
    {
      "id": "sf_rec_no",
      "source_id": "gw_new_records",
      "target_id": "task_check_crm_initial",
      "condition_name": "No new records found"
    },
    {
      "id": "sf_rec_yes",
      "source_id": "gw_new_records",
      "target_id": "task_check_crm_second",
      "condition_name": "New records found"
    },
    {
      "id": "sf_4",
      "source_id": "task_check_crm_initial",
      "target_id": "gw_crm_initial",
      "condition_name": null
    },
    {
      "id": "sf_crm_yes",
      "source_id": "gw_crm_initial",
      "target_id": "task_register_defaulters",
      "condition_name": "New returns exist"
    },
    {
      "id": "sf_crm_no",
      "source_id": "gw_crm_initial",
      "target_id": "task_check_crm_second",
      "condition_name": "No new returns exist"
    },
    {
      "id": "sf_5",
      "source_id": "task_register_defaulters",
      "target_id": "task_check_advised_codes",
      "condition_name": null
    },
    {
      "id": "sf_6",
      "source_id": "task_check_advised_codes",
      "target_id": "gw_advised",
      "condition_name": null
    },
    {
      "id": "sf_adv_not",
      "source_id": "gw_advised",
      "target_id": "task_produce_table",
      "condition_name": "Not previously advised"
    },
    {
      "id": "sf_adv_yes",
      "source_id": "gw_advised",
      "target_id": "task_check_230_deadline",
      "condition_name": "Previously advised"
    },
    {
      "id": "sf_7",
      "source_id": "task_produce_table",
      "target_id": "evt_send_table_am",
      "condition_name": null
    },
    {
      "id": "sf_8",
      "source_id": "evt_send_table_am",
      "target_id": "task_check_230_deadline",
      "condition_name": null
    },
    {
      "id": "sf_9",
      "source_id": "task_check_230_deadline",
      "target_id": "gw_230_deadline",
      "condition_name": null
    },
    {
      "id": "sf_230_no",
      "source_id": "gw_230_deadline",
      "target_id": "evt_alert_230",
      "condition_name": "Not completed by 2:30 pm"
    },
    {
      "id": "sf_230_yes",
      "source_id": "gw_230_deadline",
      "target_id": "gw_230_merge",
      "condition_name": "Completed before 2:30 pm"
    },
    {
      "id": "sf_10",
      "source_id": "evt_alert_230",
      "target_id": "gw_230_merge",
      "condition_name": null
    },
    {
      "id": "sf_11",
      "source_id": "gw_230_merge",
      "target_id": "task_check_crm_second",
      "condition_name": null
    },
    {
      "id": "sf_12",
      "source_id": "task_check_crm_second",
      "target_id": "gw_crm_second",
      "condition_name": null
    },
    {
      "id": "sf_crm2_yes",
      "source_id": "gw_crm_second",
      "target_id": "task_reconcile",
      "condition_name": "New returns filed"
    },
    {
      "id": "sf_crm2_no",
      "source_id": "gw_crm_second",
      "target_id": "task_check_400_deadline",
      "condition_name": "No new returns filed"
    },
    {
      "id": "sf_13",
      "source_id": "task_reconcile",
      "target_id": "task_check_400_deadline",
      "condition_name": null
    },
    {
      "id": "sf_14",
      "source_id": "task_check_400_deadline",
      "target_id": "gw_400_deadline",
      "condition_name": null
    },
    {
      "id": "sf_400_no",
      "source_id": "gw_400_deadline",
      "target_id": "evt_alert_400",
      "condition_name": "Not completed by 4:00 pm"
    },
    {
      "id": "sf_400_yes",
      "source_id": "gw_400_deadline",
      "target_id": "gw_400_merge",
      "condition_name": "Completed before 4:00 pm"
    },
    {
      "id": "sf_15",
      "source_id": "evt_alert_400",
      "target_id": "gw_400_merge",
      "condition_name": null
    },
    {
      "id": "sf_16",
      "source_id": "gw_400_merge",
      "target_id": "evt_end",
      "condition_name": null
    }
  ],
  "pools": [],
  "message_flows": [],
