      "name": "Table of defaulting accounts"
    }
  ],
  "data_stores": [
    {
      "id": "ds_db",
      "name": "Account Defaulter Table / Database"
    },
    {
      "id": "ds_crm",
      "name": "CRM System"
    }
  ],
  "inter_arrival_time": {
    "distribution": "fixed",
    "value": 1.0,
    "unit": "minutes",
    "is_placeholder": true,
    "source": "default_missing_duration"
  },
  "simulation_duration": null,
  "simulation_duration_unit": "hours"
